contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address logger, bool status) public {
        require(logger != address(0));

        bool before = c.approvedToLog(logger); if (__ESBMC_reverted()) return;

        bool reverted;
        c.setApprovedLogger(logger, status); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        bool afterState = c.approvedToLog(logger); if (__ESBMC_reverted()) return;

        assert(
            (reverted && afterState == before) ||
            (!reverted && afterState == status)
        );
    }

    receive() external payable {}
}

